import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  menubarItemClassName,
  menubarMenuClassName,
  menubarPopupClassName,
  menubarRootClassName,
  menubarSeparatorClassName,
  menubarTriggerClassName,
} from "./view";

export {
  menubarItemClassName,
  menubarMenuClassName,
  menubarPopupClassName,
  menubarRootClassName,
  menubarSeparatorClassName,
  menubarTriggerClassName,
} from "./view";

export type MenubarStyle = Readonly<Record<string, string>>;

export type RootViewConfig = Readonly<{
  children: readonly Html[];
  className?: string | undefined;
  style?: MenubarStyle | undefined;
}>;

export type MenuViewConfig = Readonly<{
  children: readonly Html[];
  className?: string | undefined;
  style?: MenubarStyle | undefined;
}>;

export type TriggerViewConfig<ParentMessage> = Readonly<{
  children: readonly Html[];
  onToggle?: ParentMessage | undefined;
  open?: boolean | undefined;
  className?: string | undefined;
  style?: MenubarStyle | undefined;
}>;

export type PopupViewConfig = Readonly<{
  open?: boolean | undefined;
  children: readonly Html[];
  className?: string | undefined;
  style?: MenubarStyle | undefined;
}>;

export type ItemViewConfig<ParentMessage> = Readonly<{
  children: readonly Html[];
  onSelect?: ParentMessage | undefined;
  disabled?: boolean | undefined;
  className?: string | undefined;
  style?: MenubarStyle | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const rootView = <ParentMessage>({
  children,
  className,
  style,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "menubar"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(menubarRootClassName, className)),
    ],
    children
  );
};

export const menuView = <ParentMessage>({
  children,
  className,
  style,
}: MenuViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(menubarMenuClassName, className)),
    ],
    children
  );
};

export const triggerView = <ParentMessage>({
  children,
  onToggle,
  open = false,
  className,
  style,
}: TriggerViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.Attribute("role", "menuitem"),
      h.Attribute("aria-haspopup", "menu"),
      h.Attribute("aria-expanded", open ? "true" : "false"),
      ...(open ? [h.Attribute("data-open", "")] : []),
      ...(onToggle === undefined ? [] : [h.OnClick(onToggle)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(menubarTriggerClassName, className)),
    ],
    children
  );
};

export const popupView = <ParentMessage>({
  open = true,
  children,
  className,
  style,
}: PopupViewConfig): Html => {
  const h = html<ParentMessage>();

  if (!open) {
    return h.div([h.Hidden(true)], []);
  }

  return h.div(
    [
      h.Attribute("role", "menu"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(menubarPopupClassName, className)),
    ],
    children
  );
};

export const itemView = <ParentMessage>({
  children,
  onSelect,
  disabled = false,
  className,
  style,
}: ItemViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "menuitem"),
      ...(disabled ? [h.Attribute("data-disabled", "")] : []),
      ...(onSelect === undefined ? [] : [h.OnClick(onSelect)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(menubarItemClassName, className)),
    ],
    children
  );
};

export const separatorView = <ParentMessage>({
  className,
  style,
}: Omit<MenuViewConfig, "children">): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "separator"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(menubarSeparatorClassName, className)),
    ],
    []
  );
};

export const menubarRootClassName =
  "inline-flex items-center gap-1 rounded-lg border border-gray-200 bg-white p-1 shadow-sm";

export const menubarMenuClassName = "relative";

export const menubarTriggerClassName =
  "inline-flex items-center justify-center rounded-md px-3 py-2 text-base font-medium text-gray-700 transition hover:bg-gray-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600 data-[open]:bg-gray-100";

export const menubarPopupClassName =
  "absolute left-0 top-full z-20 mt-1 min-w-44 overflow-hidden rounded-lg border border-gray-200 bg-white py-1 shadow-lg";

export const menubarItemClassName =
  "px-3 py-2 text-base text-gray-700 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const menubarSeparatorClassName = "my-1 h-px bg-gray-200";

import { Scene } from "foldkit";
import { html } from "foldkit/html";
import { describe, expect, test } from "vitest";

import * as Menubar from ".";

const view = () => {
  const h = html<never>();

  return Menubar.rootView<never>({
    children: [
      Menubar.menuView<never>({
        children: [
          Menubar.triggerView<never>({
            open: true,
            children: [h.span([], ["File"])],
          }),
          Menubar.popupView<never>({
            children: [
              Menubar.itemView<never>({
                children: [h.span([], ["New"])],
              }),
            ],
          }),
        ],
      }),
    ],
  });
};

describe("Base UI Menubar registry component", () => {
  test("renders static menubar anatomy", () => {
    Scene.scene(
      {
        update: (model: undefined) => [model, []] as const,
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.role("menubar")).toExist(),
      Scene.expect(Scene.role("menuitem", { name: "File" })).toHaveAttr(
        "aria-expanded",
        "true"
      ),
      Scene.expect(Scene.role("menu")).toExist(),
      Scene.expect(Scene.role("menuitem", { name: "New" })).toExist()
    );
  });

  test("supports controlled closed popup state", () => {
    const h = html<never>();

    Scene.scene(
      {
        update: (model: undefined) => [model, []] as const,
        view: () =>
          Menubar.rootView<never>({
            children: [
              Menubar.menuView<never>({
                children: [
                  Menubar.triggerView<never>({
                    open: false,
                    children: [h.span([], ["File"])],
                  }),
                  Menubar.popupView<never>({
                    open: false,
                    children: [
                      Menubar.itemView<never>({
                        children: [h.span([], ["New"])],
                      }),
                    ],
                  }),
                ],
              }),
            ],
          }),
      },
      Scene.with(undefined),
      Scene.expect(Scene.role("menuitem", { name: "File" })).toHaveAttr(
        "aria-expanded",
        "false"
      ),
      Scene.expect(Scene.role("menu")).not.toExist()
    );
  });

  test("exports Base UI menubar class hooks", () => {
    expect(Menubar.menubarRootClassName).toContain("inline-flex");
    expect(Menubar.menubarTriggerClassName).toContain("data-[open]");
    expect(Menubar.menubarPopupClassName).toContain("shadow");
  });
});
